(((e.aggregate_type='collaboration_action' AND e.event_type IN ('collaboration.action.create','collaboration.action.complete','collaboration.action.reassign','collaboration.action.cancel') AND EXISTS(SELECT 1 FROM collaboration_action_cards s WHERE s.id=e.aggregate_id AND s.source_type='field_service_order' AND s.company_id=e.payload_json::jsonb->>'companyId' AND s.version>=e.aggregate_version)) OR (e.aggregate_type='collaboration_relation' AND e.event_type IN ('collaboration.relation.create','collaboration.relation.remove') AND EXISTS(SELECT 1 FROM collaboration_record_relations s WHERE s.id=e.aggregate_id AND ((s.source_type='field_service_order' AND s.target_type IN ('field_service_order','support_ticket')) OR (s.source_type='support_ticket' AND s.target_type='field_service_order')) AND s.company_id=e.payload_json::jsonb->>'companyId' AND s.version>=e.aggregate_version))) OR (e.aggregate_type='inbox_delivery' AND e.event_type='inbox.delivery.state' AND e.aggregate_version=1 AND EXISTS(SELECT 1 FROM inbox_deliveries d JOIN inbox_events n ON n.id=d.event_id AND n.company_id=d.company_id WHERE d.id=e.aggregate_id AND d.company_id=e.payload_json::jsonb->>'companyId' AND n.source_type IN('field_service_order','operational_exception','collaboration_action','support_ticket','stock_count','invoice','journal') AND erpx_field_push_source(n.source_type,n.source_id,n.company_id)) AND EXISTS(SELECT 1 FROM command_receipts r WHERE r.command_id=e.command_id AND (CASE WHEN r.result_json IS JSON OBJECT THEN r.result_json::jsonb ELSE '{}'::jsonb END)->'_nativeFieldInbox'='true'::jsonb)))
